import json,zlib,subprocess,statistics,hashlib
from pathlib import Path
T=Path('/tmp/unisacc-v009-private-load');paths=['plain.com','compressed.com'];r={}
for mode in [0,1]:
 name='warm_cached' if not mode else 'F_NOCACHE_fd_bypass_not_cold_disk';r[name]={p:[] for p in paths}
 for i in range(5):
  for p in (paths if i%2==0 else list(reversed(paths))):
   x=subprocess.run([str(T/'readprobe'),str(mode),'20',str(T/p)],capture_output=True,timeout=10);assert x.returncode==0,(p,mode,x.returncode,x.stderr)
   ns,n,crc=map(int,x.stdout.split());data=(T/p).read_bytes();assert (n,crc)==(len(data),zlib.crc32(data))
   r[name][p].append(ns/20)
 for p in paths: print(name,p,statistics.median(r[name][p])/1e6,'ms',flush=True)
