import subprocess,time,statistics,json,hashlib,platform,os
from pathlib import Path
T=Path('/tmp/unisacc-v009-private-load');sources=Path('examples/apps/calc.c');labels=['package_read_ns','directory_and_init_ns','inflate_ns','crc_ns','model_parse_ns','execute_ns','loads','inflates'];records={}
paths={'plain':T/'plain.com','compressed':T/'compressed.com','shipped':Path('unisacc.com').resolve()}
expected=None
def call(key,args):
 global expected
 path=paths[key];start=time.perf_counter();r=subprocess.run(['/bin/sh',str(path),*args],capture_output=True,timeout=15);elapsed=time.perf_counter()-start
 assert r.returncode==0,(key,args,r.returncode,r.stderr)
 result=dict(seconds=elapsed,stdout_sha256=hashlib.sha256(r.stdout).hexdigest())
 if args==['-run',str(sources)]:
  if expected is None:expected=r.stdout
  assert r.stdout==expected,(key,'wrong stdout')
 if key!='shipped' and args!=['--version']:
  lines=[l for l in r.stderr.decode().splitlines() if l.startswith('PROBE ')];assert len(lines)==1
  values=list(map(int,lines[0].split()[1:]));assert len(values)==len(labels);result['phases']=dict(zip(labels,values))
 return result
for key in paths:call(key,['-run',str(sources)]);call(key,['--version'])
for key in paths:records[key]=dict(calc=[],startup=[])
for i in range(5):
 for key in (['plain','compressed','shipped'] if i%2==0 else ['shipped','compressed','plain']):
  records[key]['calc'].append(call(key,['-run',str(sources)]));records[key]['startup'].append(call(key,['--version']))
summary={}
for key in paths:
 summary[key]={name:statistics.median(x['seconds'] for x in records[key][name]) for name in ['calc','startup']}
 if key!='shipped':summary[key]['phases']={k:statistics.median(x['phases'][k] for x in records[key]['calc']) for k in labels}
 print(key,json.dumps(summary[key]),flush=True)
# Images at O2 must be byte-identical too, not merely matching stdout.
for key in paths:
 out=T/(key+'.image');call(key,['-O2',str(sources),'-o',str(out)])
assert (T/'plain.image').read_bytes()==(T/'compressed.image').read_bytes()==(T/'shipped.image').read_bytes()
result=dict(platform=platform.platform(),source_sha256=hashlib.sha256(sources.read_bytes()).hexdigest(),records=records,summary=summary,files={k:dict(sha256=hashlib.sha256(v.read_bytes()).hexdigest(),bytes=v.stat().st_size) for k,v in paths.items()},image_sha256=hashlib.sha256((T/'plain.image').read_bytes()).hexdigest(),scope='Warm APE cache, same private instrumented driver prefix and unchanged model text/resources. Valid-input prototype only. Not production error-path or full-platform acceptance.')
(T/'bench-result.json').write_text(json.dumps(result,indent=2)+'\n')

